import{_ as t}from"./chunks/Audio.COine8Wh.js";import{c as r,o as s,j as i,G as a,ae as n,a as o}from"./chunks/framework.Bw0Gm4PQ.js";const u=JSON.parse('{"title":"RESTORING AMERICAN AIRSPACE SOVEREIGNTY","description":"","frontmatter":{"legisId":"2025-06-06-restoring-american-airspace-sovereignty","title":"RESTORING AMERICAN AIRSPACE SOVEREIGNTY","sourceUrl":"https://www.whitehouse.gov/presidential-actions/2025/06/restoring-american-airspace-sovereignty/","publishDate":"2025-06-06T17:23:09-04:00","head":[["script",{"type":"application/ld+json"},"[{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"BreadcrumbList\\",\\"itemListElement\\":[{\\"@type\\":\\"ListItem\\",\\"position\\":1,\\"name\\":\\"Home\\",\\"item\\":\\"https://vladroff.github.io/legis\\"},{\\"position\\":2,\\"@type\\":\\"ListItem\\",\\"name\\":\\"Executive Orders\\",\\"item\\":\\"https://vladroff.github.io/legis/executive-orders\\"},{\\"position\\":3,\\"@type\\":\\"ListItem\\",\\"name\\":\\"RESTORING AMERICAN AIRSPACE SOVEREIGNTY\\",\\"item\\":\\"https://vladroff.github.io/legis/executive-orders/2025-06-06-restoring-american-airspace-sovereignty\\"}]},{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"Article\\",\\"headline\\":\\"RESTORING AMERICAN AIRSPACE SOVEREIGNTY\\",\\"description\\":\\"Summaries of US legislation.\\",\\"url\\":\\"https://vladroff.github.io/legis/executive-orders/2025-06-06-restoring-american-airspace-sovereignty\\",\\"datePublished\\":\\"2025-06-06T17:23:09-04:00\\",\\"dateModified\\":1775009000000,\\"mainEntityOfPage\\":\\"https://vladroff.github.io/legis/executive-orders/2025-06-06-restoring-american-airspace-sovereignty\\",\\"author\\":{\\"@type\\":\\"Organization\\",\\"name\\":\\"Legis\\"},\\"publisher\\":{\\"@type\\":\\"Organization\\",\\"name\\":\\"Legis\\"}}]"]]},"headers":[],"relativePath":"executive-orders/2025-06-06-restoring-american-airspace-sovereignty.md","filePath":"executive-orders/2025-06-06-restoring-american-airspace-sovereignty.md","lastUpdated":1775009000000}'),l={name:"executive-orders/2025-06-06-restoring-american-airspace-sovereignty.md"},m=Object.assign(l,{setup(c){return(d,e)=>(s(),r("div",null,[e[0]||(e[0]=i("h1",{id:"restoring-american-airspace-sovereignty",tabindex:"-1"},[o("RESTORING AMERICAN AIRSPACE SOVEREIGNTY "),i("a",{class:"header-anchor",href:"#restoring-american-airspace-sovereignty","aria-label":'Permalink to "RESTORING AMERICAN AIRSPACE SOVEREIGNTY"'},"​")],-1)),a(t),e[1]||(e[1]=n('<p>Published on Friday, June 6, 2025</p><ul><li>The Executive Order addresses the threats posed by unmanned aircraft systems (UAS), highlighting their use by criminals and terrorists.</li><li>It states that immediate actions are required to ensure the safety and security of American airspace against UAS incursions.</li></ul><p><strong>Definitions:</strong></p><ul><li><strong>UAS</strong>: Defined as per 49 U.S.C. 44801.</li><li><strong>Critical Infrastructure</strong>: Defined as per 42 U.S.C. 5195c(e) and includes systems in designated sectors.</li><li><strong>Sector Risk Management Agency (SRMA)</strong>: As defined in 6 U.S.C. 650 and NSM-22.</li></ul><p><strong>Key Policies:</strong></p><ul><li>The U.S. aims to control its national airspace and protect the public and critical infrastructure from UAS threats.</li><li>A Federal Task Force to Restore American Airspace Sovereignty will be established, chaired by the Assistant to the President for National Security Affairs.</li></ul><p><strong>Actions by FAA:</strong></p><ul><li>The FAA Administrator is required to: <ul><li>Submit a notice of proposed rulemaking for restricting drone flights over critical facilities.</li><li>Coordinate national security assessments with relevant agencies.</li><li>Provide online access to Notices to Airmen and Temporary Flight Restrictions within 180 days.</li></ul></li></ul><p><strong>Enforcement Measures:</strong></p><ul><li>The Attorney General, in coordination with the FAA, will enforce laws against unsafe drone operations and propose legislative changes to enhance penalties.</li><li>Grant programs will be made available to eligible State, local, tribal, and territorial agencies for UAS detection and tracking.</li></ul><p><strong>Technological Measures:</strong></p><ul><li>Agencies are instructed to use existing authorities to detect and track UAS.</li><li>Updates to regulations regarding UAS detection technology will be revised within 30 days.</li><li>Information access related to UAS will be provided to agencies for enforcement purposes within 60 days.</li></ul><p><strong>Recommendations Timeline:</strong></p><ul><li>Within 90 days, a recommendation on designating border and critical areas as covered facilities will be submitted.</li><li>Within 30 days, UAS operational responses will be integrated into Joint Terrorism Task Forces.</li></ul><p><strong>Training Initiatives:</strong></p><ul><li>Recommendations will be implemented for establishing a National Training Center for Counter-UAS, focusing on security for major events like the FIFA World Cup 2026.</li></ul><p><strong>General Provisions:</strong></p><ul><li>The order reaffirms existing authorities and functions of executive agencies.</li><li>Compliance with applicable laws and budgetary provisions is required.</li><li>No legal rights or benefits are granted by this order to individuals or entities.</li></ul><p>Source: <a href="https://www.whitehouse.gov/presidential-actions/2025/06/restoring-american-airspace-sovereignty/" target="_blank" rel="noreferrer">https://www.whitehouse.gov/presidential-actions/2025/06/restoring-american-airspace-sovereignty/</a></p>',19))]))}});export{u as __pageData,m as default};
